<?php
namespace App\Http\Controllers;use App\Models\TransportService;use App\Services\TransportEvidenceService;use Illuminate\Http\Request;
class TransportHistoryController extends Controller {public function index(Request$r,TransportEvidenceService$e){$c=$r->user()->company_id;$q=TransportService::forCompany($c)->with(['vehicle','actualVehicle','driver.employee','actualDriver.employee','issues','arrivalSignature'])->orderByDesc('service_date');if($r->filled('from'))$q->whereDate('service_date','>=',$r->from);if($r->filled('to'))$q->whereDate('service_date','<=',$r->to);foreach(['status','transport_route_id','actual_vehicle_id','actual_driver_id']as$f)if($r->filled($f))$q->where($f,$r->$f);$services=$q->paginate(30)->withQueryString();$services->getCollection()->each(fn($s)=>$s->evidence_control=$e->evaluate($s));return view('transport.history.index',compact('services'));}}
